// === Tab: mySketch ===
// Illustration of periodic (wrap around) boundary conditions for a particle system.
// Doug L. James, Sept 2020, http://graphics.stanford.edu/~djames
let particles = [];

function setup() {
	createCanvas(windowWidth, windowHeight);

	randomizeParticles();
}

function draw() {
	setBackground();

	if(keyIsPressed) randomizeParticles();

	for(let p of particles) {
		p.update(deltaTime);// timestep pos
		applyPeriodicBC(p);
		p.draw();
	}

}

function applyPeriodicBC(particle) {
	// Periodic Boundary Conditions:
	let A = particle; 
	if(A.pos.x < 0)      A.pos.x += width;
	if(A.pos.x > width)  A.pos.x -= width;
	if(A.pos.y < 0) 		 A.pos.y += height;
	if(A.pos.y > height) A.pos.y -= height;
}

function randomizeParticles() {
	particles = [];
	for(let k=0; k<500; k++)  
		particles.push(createRandomParticle());
}

function setBackground() {
	background("black");//SVG color names :)
}


// A simple particle class
class Particle {
	constructor(x,y,vx,vy,r,c) {
		this.pos = createVector(x,y);
		this.vel = createVector(vx,vy);
		this.r  = r;//radius
		this.c  = c;//color
	}
	update(dt) {
		// Update velocity:
		// no change

		// Update position:
		this.pos.x += dt * this.vel.x;
		this.pos.y += dt * this.vel.y;
	}

	draw() {
		fill(this.c);
		circle(this.pos.x, this.pos.y, this.r);
	}
}

function createRandomParticle() {
	let radius  = abs(randomGaussian(5,15));
	let velMax  = 2;
	let randVel = p5.Vector.random2D().mult(random(velMax)/radius);
	colorMode(HSB,255);
	return new Particle(random(width), random(height), 
											randVel.x, randVel.y, radius, 
											color(random(255),random(60),random(200)));
}

